      p.cup.quaternion.slerp(this.cupQuat,a);p.lid.quaternion.slerp(this.lidQuat,a);
      if(this.animateCamera){this.studio.camera.position.lerp(this.toCamera,a);this.controls.target.lerp(this.toTarget,a);}
