    const p=this.getProduct();p.cup.visible=pose.part==='all'||pose.part==='cup';p.lid.visible=pose.part==='all'||pose.part==='lid';p.saucer.visible=pose.part==='all'||pose.part==='saucer';
    if(pose.part==='lid')p.lid.position.set(0,33,0);
